def max_distance_between_primes(nums):
    """
    Calculates the maximum distance between the indices of two prime numbers in a sequence.
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    first_prime_idx = -1
    last_prime_idx = -1

    for index, value in enumerate(nums):
        if is_prime(value):
            if first_prime_idx == -1:
                first_prime_idx = index
            last_prime_idx = index

    return last_prime_idx - first_prime_idx
